class RfswCli(Exit):
    """RfswCli command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None, expected_prompt=r"rfsw> "):
        """
        Go to rfsw_cli shell.

        :param connection: moler connection to device, terminal when command is executed
        :param prompt: Prompt of the starting shell
        :param expected_prompt: Prompt of the target shell reached after entering to rfsw_cli state
        :param newline_chars: Characters to split lines
        """
        super(RfswCli, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                      runner=runner, expected_prompt=expected_prompt)

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = "rfsw_cli"
        return cmd


